class Solution {
public:
    int countSubranges(vector<int>& nums1, vector<int>& nums2) {
        const int MOD = 1e9 + 7;
        unordered_map<int, int> dp;
        int ans = 0;
        int n = nums1.size();
        for (int i = 0; i < n; i++) {
            int x = nums1[i], y = nums2[i];
            unordered_map<int, int> nextDp;
            nextDp[x] = (nextDp[x] + 1) % MOD;
            nextDp[-y] = (nextDp[-y] + 1) % MOD;
            for (auto& [s, count] : dp) {
                nextDp[s + x] = (nextDp[s + x] + count) % MOD;
                nextDp[s - y] = (nextDp[s - y] + count) % MOD;
            }
            if (nextDp.count(0)) {
                ans = (ans + nextDp[0]) % MOD;
            }
            dp = move(nextDp);
        }
        return ans;
    }
};

class Solution {
    public int countSubranges(int[] nums1, int[] nums2) {
        final int MOD = 1_000_000_007;
        Map<Integer, Integer> dp = new HashMap<>();
        int ans = 0;
        int n = nums1.length;
        for (int i = 0; i < n; i++) {
            int x = nums1[i], y = nums2[i];
            Map<Integer, Integer> nextDp = new HashMap<>();
            nextDp.put(x, (nextDp.getOrDefault(x, 0) + 1) % MOD);
            nextDp.put(-y, (nextDp.getOrDefault(-y, 0) + 1) % MOD);
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int s = entry.getKey();
                int count = entry.getValue();
                nextDp.put(s + x, (nextDp.getOrDefault(s + x, 0) + count) % MOD);
                nextDp.put(s - y, (nextDp.getOrDefault(s - y, 0) + count) % MOD);
            }
            ans = (ans + nextDp.getOrDefault(0, 0)) % MOD;
            dp = nextDp;
        }
        return ans;
    }
}

